def avg(xs):
    return sum(xs) / len(xs)


def median(xs):
    if not xs:
        raise ValueError("median() arg is an empty sequence")
    ys = sorted(xs)
    mid = len(ys) // 2
    if len(ys) % 2:
        return ys[mid]
    return (ys[mid - 1] + ys[mid]) / 2

